import{z as A,x as i,o as e,c as l,q as t,j as o,D as a,d as n,s as B,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"纵向一体化的动机","description":"","frontmatter":{"title":"纵向一体化的动机","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/vertical-integration-why.md","filePath":"econ/vertical-integration-why.md","lastUpdated":1791063341000}'),p={name:"econ/vertical-integration-why.md"};function d(c,E,h,D,g,m){const r=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=t('<h1 id="纵向一体化的动机" tabindex="-1">纵向一体化的动机 <a class="header-anchor" href="#纵向一体化的动机" aria-label="Permalink to &quot;纵向一体化的动机&quot;">​</a></h1><div class="epigraph"><p>市场与企业不是两种成本函数，而是同一成本的两种边界：合同写得到的地方用合同，写不到的地方用所有权。</p><footer>—— 据 Coase, The Nature of the Firm, 1937；Grossman and Hart, JPE 1986 整理</footer></div><p><a href="/econ/quality-reputation-choosing">上一课</a>把质量写成跨期承诺问题，押金是溢价流。本课把承诺问题搬进供应链：上下游各自的专用投资与加价，靠什么治理。分工先钉死：<a href="/econ/vertical-restraints">纵向约束</a>课讲<strong>合同替代</strong>——双重加价可用两部收费复制一体化，服务外部性可用转售价格维持；本课讲<strong>产权边界</strong>：合同写不到时，一体化才亲自上场。双重加价在本课只剩一句：合同能修的边界，不必动所有权。工具已备好：<a href="/econ/hold-up-gh">套牢</a>给出专用投资的准租暴露，<a href="/econ/incomplete-contracts">不完全合同</a>给出补偿条款为何写不了——本课拼成 make-or-buy 的完整答案。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自建还是外购，动机有三层，份量递增。其一，<strong>交易成本</strong>：Coase 1937 的原始问题——使用价格机制本身有成本（搜寻、议价、履约），交易越频繁、越不确定、资产越专用，市场采购越贵；Williamson 1985 收成治理形式与交易属性的匹配表。其二是<strong>双重加价消除</strong>：约束课已给出合同何时足以修复。其三是<strong>投资协调</strong>：两家都做关系专用投资，事前都怕被事后套牢，双双投资不足；关键投资与状态对法庭不可验证，合同修不了这一层。Grossman–Hart 1986 与 Hart–Moore 1990 重新定义所有权：<strong>一体化不是合并成本曲线，是把剩余控制权——合同未规定之事的决定权——转移给一方</strong>。</p>',5)),(e(),o(s,null,{default:a(()=>[B(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E4%B8%93%E7%94%A8%E6%80%A7%E6%8A%95%E8%B5%84%22%5D%20--%3E%20HOLD%5B%22%E5%A5%97%E7%89%A2%E9%A3%8E%E9%99%A9%E4%B8%8E%E6%8A%95%E8%B5%84%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20INC%5B%22%E5%90%88%E5%90%8C%E4%B8%8D%E5%AE%8C%E5%85%A8%EF%BC%9A%E5%85%B3%E9%94%AE%E9%A1%B9%E4%B8%8D%E5%8F%AF%E9%AA%8C%E8%AF%81%22%5D%20--%3E%20CHOICE%5B%22%E6%B2%BB%E7%90%86%E9%80%89%E6%8B%A9%22%5D%0A%20%20HOLD%20--%3E%20CHOICE%0A%20%20CHOICE%20--%3E%20A%5B%22%E5%90%88%E5%90%8C%EF%BC%9A%E7%BA%B5%E5%90%91%E7%BA%A6%E6%9D%9F%E8%AF%BE%22%5D%0A%20%20CHOICE%20--%3E%20B%5B%22%E6%89%80%E6%9C%89%E6%9D%83%EF%BC%9A%E4%B8%80%E4%BD%93%E5%8C%96%22%5D%0A%20%20B%20--%3E%20RES%5B%22%E5%89%A9%E4%BD%99%E6%8E%A7%E5%88%B6%E6%9D%83%E8%BD%AC%E7%A7%BB%20%E2%86%92%20%E6%8A%95%E8%B5%84%E6%BF%80%E5%8A%B1%E5%86%8D%E5%88%86%E9%85%8D%22%5D%0A%20%20RES%20--%3E%20COST%5B%22%E5%8F%8D%E5%90%91%E5%8A%9B%EF%BC%9A%E5%86%85%E9%83%A8%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><span class="marginnote">GHM 的分配规则：<strong>谁的投资更关键，谁拥有资产</strong>。上游投资的社会边际产品高，则上游一体化下游；反之反是。两家投资都关键时，非一体化反而最优——分拆控制权本身就是激励设计。</span></p><p><span class="marginnote">术语翻译：剩余控制权就是合同没写到的那些事的决定权。合同写得再厚也写不完——机器闲置的晚上给谁用、需求突然翻倍先供谁——这些「没想到」的处置权，跟着资产所有权走，不跟价格走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型骨架：两家、两资产，所有权决定关系破裂时各自拿什么走出谈判——拥有资产的一方外部选择更厚，分租更多，激励更强。一体化不免费：它抬高被合并方的激励、压低另一方的，还叠上内部代理成本——被收购部门的经理不再承受市场竞争的纪律，创新与成本控制变软。所以 make-or-buy 的正确问法不是「哪种便宜」，而是「剩余控制权放在哪一端，两边的投资加起来最大」。经验上可检验：Lafontaine–Slade 2007 综述的特许对直营数据——测量越难、品牌押金越重（接上一课）、地方努力越关键的业态越偏特许这类<strong>中间治理</strong>；资产专用而测量容易的环节，直营占比高。治理是连续谱，不是开关。</p><p>错在哪：把一体化当规模经济的合并，读不出激励转移；或把 make-or-buy 写成纯交易成本比较——芝加哥对威廉姆森的批评正在此：长期合同、声誉与竞争能缓解套牢，专用性不必然推向一体化。</p><p><span class="marginnote">直觉类比：谈判分蛋糕的比例，取决于你空手离开桌子时还能吃什么。拥有资产的一方离桌后仍可拿资产另找买家，所以敢要价；被合并走的人空手离桌，分成自然变薄——所有权正是通过「破裂时你手里剩什么」这条通道改变投资激励的。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三个动机常叠加，拆法是问反事实改了哪一变量：交易成本主导，改的是<strong>频率与不确定性</strong>；双重加价主导，改的是<strong>合同工具</strong>，先于所有权试一遍；投资协调主导，改的是<strong>外部选择</strong>——谁的退出更薄，谁被套牢。Stigler 1951 的生命周期是动态版：新兴产业上游规模小，养不起专业供应商，市场扩大后一体化逐级<strong>解体</strong>外包——一体化率是均衡变量，不是企业的性格。这解释同行内并存的混合形态：核心模具自建、通用件外购、渠道特许。</p><p>一体化深的企业售后常失压：不是垄断加成，是内部部门失去外部标尺，成本与质量同时松动——内部组织成本是真金白银，进权衡，不当注脚。</p>',9)),(e(),o(s,null,{default:a(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20OWN%5B%22%E8%B0%81%E6%8B%A5%E6%9C%89%E5%85%B3%E9%94%AE%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20EXIT%5B%22%E7%A0%B4%E8%A3%82%E6%97%B6%E8%87%AA%E5%B7%B1%E7%9A%84%E5%A4%96%E9%83%A8%E9%80%89%E6%8B%A9%22%5D%0A%20%20EXIT%20--%3E%20SH%5B%22%E8%B0%88%E5%88%A4%E4%B8%AD%E5%88%86%E5%88%B0%E7%9A%84%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20SH%20--%3E%20INV%5B%22%E4%BA%8B%E5%89%8D%E4%B8%93%E7%94%A8%E6%8A%95%E8%B5%84%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20OWN%20--%3E%20ALT%5B%22%E5%AF%B9%E6%96%B9%E5%A4%B1%E5%8E%BB%E8%B5%84%E4%BA%A7%22%5D%0A%20%20ALT%20--%3E%20SH2%5B%22%E5%AF%B9%E6%96%B9%E5%A4%96%E9%83%A8%E9%80%89%E6%8B%A9%E5%8F%98%E8%96%84%22%5D%0A%20%20SH2%20--%3E%20INV2%5B%22%E5%AF%B9%E6%96%B9%E6%8A%95%E8%B5%84%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20INV%20--%3E%20TS%5B%22%E5%8F%8C%E6%96%B9%E6%8A%95%E8%B5%84%E5%8A%A0%E6%80%BB%20%3D%20%E6%80%BB%E5%89%A9%E4%BD%99%22%5D%0A%20%20INV2%20--%3E%20TS%0A%20%20INT%5B%22%E5%86%85%E9%83%A8%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%22%5D%20--%3E%20TS%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">常见误区：初学者容易把「这家公司就喜欢什么都自己做」当成一体化的原因。实际上一体化率随市场规模移动——Stigler 的生命周期说产业幼年养不起专业供应商只好自建，市场长大后逐级外包解体。是企业边界在适应，不是企业性格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做纵向合并的审查要件：纵向合并的主要嫌疑是提高对手成本与圈除市场，是<a href="/econ/predation-exclusion">掠夺与排他</a>里排他一支的延伸；<a href="/econ/merger-simulation">合并模拟</a>的横向反事实不能照搬。平台生态是双边结构，本课只给单链。数据老坑：治理内生，OLS 混淆效率与激励，要用工艺或法律变动做准实验；测量命题随数据环境移动，剩余控制权的逻辑不动。加深层到此收束：产品会换代（竞赛）、需求可塑造（广告）、质量靠押金（声誉）、边界由控制权定（本课）；后课默认这套语言；树序接下去换到公共财政。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一体化是剩余控制权的边界移动，不是成本函数的合并。</li><li>三动机分层：交易成本、双重加价（合同可解就不动所有权）、投资协调（GHM 的所有权分配）。</li><li>谁的投资更关键谁拥有资产；一体化的反向力是内部代理成本与激励变软。</li><li>治理是连续谱：特许与直营的分布随测量难度与品牌押金系统变化。</li><li>出处：Coase 1937；Williamson 1985；Grossman–Hart 1986；Hart–Moore 1990；Lafontaine–Slade 2007。</li></ul>',5))])}const u=A(p,[["render",d]]);export{_ as __pageData,u as default};
